import { chromium, webkit } from 'playwright';
const base=process.env.KP_AUDIT_URL||'http://127.0.0.1:4173/';
const ids=['florian','rynek','maria','maius','wawel','dragon','szeroka','placnowy','bernatek','ghetto','tomasza','planty'];
const pic=(id,i)=>'data:image/svg+xml;base64,'+Buffer.from(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 150"><rect width="200" height="150" fill="hsl(${i*28} 28% 55%)"/><text x="10" y="80" fill="white" font-size="18">${id}</text></svg>`).toString('base64');
const iso=(d,h)=>`2026-08-${String(d).padStart(2,'0')}T${String(h).padStart(2,'0')}:00:00+02:00`;
function make(){const missionEvidence={},missionStatus={},visited=[];ids.forEach((id,i)=>{const d=i<5?11:i<10?12:13,h=i<5?9+i:i<10?9+i-5:10+i-10,t=iso(d,h);missionEvidence[id]={id,verified:true,photo:pic(id,i),title:`Recuerdo ${id}`,comment:`old ${id}`,by:i%2?'Laura':'Ismael',completedAt:t,updatedAt:t};missionStatus[id]={done:true,updatedAt:t};visited.push(id)});missionEvidence.auschwitz={id:'auschwitz',verified:true,extra:true,photo:pic('auschwitz',13),title:'Auschwitz-Birkenau',comment:'memory',by:'Ambos',completedAt:iso(12,8),updatedAt:iso(12,8)};return{visited,missionStatus,missionEvidence,memories:[],expenses:[],config:{dailyTarget:21,fixedPaid:0},updatedAt:iso(13,19)}}
for(const [engineName,engine] of [['chromium',chromium],['webkit',webkit]]){
 const initial=make(),fresh='2026-08-14T00:01:00+02:00';const browser=await engine.launch({headless:true}),context=await browser.newContext({viewport:{width:390,height:844},serviceWorkers:'block'});await context.addInitScript(s=>localStorage.setItem('krakowPocketCoop',JSON.stringify(s)),initial);
 let server=structuredClone(initial),phase='boot';const network=[];
 await context.route('https://ahzmwkztlakejmrvgcdm.supabase.co/rest/v1/rpc/**',async r=>{const u=r.request().url(),at=Date.now();if(u.includes('adventure_get')){network.push({at,phase,type:'GET',server:server.missionEvidence?.bernatek?.title,ts:server.missionEvidence?.bernatek?.updatedAt,mem:server.memories?.length});return r.fulfill({status:200,contentType:'application/json',body:JSON.stringify(server)})}if(u.includes('adventure_put')){let incoming={};try{incoming=JSON.parse(r.request().postData()||'{}').p_state||{}}catch{};network.push({at,phase,type:'PUT',incoming:incoming.missionEvidence?.bernatek?.title,ts:incoming.missionEvidence?.bernatek?.updatedAt,before:server.missionEvidence?.bernatek?.title,mem:incoming.memories?.length});server=structuredClone(incoming);return r.fulfill({status:200,contentType:'application/json',body:'{}'})}return r.fulfill({status:200,body:'{}'})});
 const page=await context.newPage();await page.goto(base,{waitUntil:'domcontentloaded'});await page.waitForFunction(()=>window.KP_STATE_BRIDGE?.version==='1.9'&&window.KP_STATE_BRIDGE?.bridgeReconciliationRevision==='20260812g'&&window.KP_ALBUM_V5?.version==='5.0'&&window.KP_ALBUM_NEXT?.version==='6.1'&&window.KP_ALBUM_NEXT?.singleRefreshOwner===true,{timeout:20000});await page.waitForTimeout(1900);await page.evaluate(()=>document.querySelector('.tab[data-panel="diary"]')?.click());await page.waitForTimeout(250);await page.locator('#kpAlbumV5Open').click();const f=page.frameLocator('#kpAlbumV5Frame');await f.locator('.photo-card').first().waitFor();await f.locator('#storyAlbum').click();
 phase='local-edits';for(const [title,note] of [['ONE','first'],['TWO','second'],['THREE','third']]){await page.evaluate(([title,note])=>{memoryTitle.value=title;memoryNote.value=note;memoryPlace.value='Cracovia';memoryForm.requestSubmit()},[title,note]);await page.waitForTimeout(900)}await page.waitForTimeout(1900);await f.locator('#storyMode .overlay-close').click();await page.waitForTimeout(1600);await f.locator('html').evaluate(()=>{document.documentElement.style.scrollBehavior='auto';scrollTo(0,180)});await page.waitForTimeout(150);await page.evaluate(()=>{memoryTitle.value='FOUR';memoryNote.value='scroll';memoryPlace.value='Cracovia';memoryForm.requestSubmit()});await page.waitForTimeout(2000);
 phase='baseline';server=structuredClone(JSON.parse(await page.evaluate(()=>localStorage.getItem('krakowPocketCoop'))));network.push({at:Date.now(),phase,type:'BASELINE',server:server.missionEvidence?.bernatek?.title,mem:server.memories?.length});
 phase='inject';server.missionEvidence.bernatek={...server.missionEvidence.bernatek,title:'REMOTE',comment:'remote',by:'Laura',updatedAt:fresh};server.updatedAt=fresh;network.push({at:Date.now(),phase,type:'INJECT',server:'REMOTE'});
 phase='reconnect';await page.evaluate(()=>document.getElementById('reconnectCloud')?.click());
 const samples=[];for(let i=0;i<30;i++){await page.waitForTimeout(500);samples.push(await page.evaluate(i=>{let s={};try{s=JSON.parse(localStorage.getItem('krakowPocketCoop')||'{}')}catch{};const p=window.KP_STATE_BRIDGE?.protectedMissionEvidence?.()||{};return{i,local:s.missionEvidence?.bernatek?.title,localTs:s.missionEvidence?.bernatek?.updatedAt,protected:p.bernatek?.title,protectedTs:p.bernatek?.updatedAt,album:window.KP_ALBUM_V5?.html().includes('REMOTE'),mem:s.memories?.length,htmlMem:['ONE','TWO','THREE','FOUR'].every(x=>window.KP_ALBUM_V5?.html().includes(x)),sync:document.getElementById('syncText')?.textContent}},i))}
 const out={engine:engineName,server:{title:server.missionEvidence?.bernatek?.title,ts:server.missionEvidence?.bernatek?.updatedAt,mem:server.memories?.length},samples,network};console.log(JSON.stringify(out,null,2));if(samples.some(x=>x.local!=='REMOTE'||x.protected!=='REMOTE'||!x.album||x.mem<4||!x.htmlMem)||server.missionEvidence?.bernatek?.title!=='REMOTE'||server.memories?.length<4)process.exitCode=1;await browser.close();
}